<?php $base='/research/'.$r['slug'];$sourceUrl=fn($page)=>$base.'/resources?'.http_build_query(array_merge($resources['filters'],['page'=>$page])); ?>
<div class="page-heading reader-heading resource-heading"><h1>Resources &amp; sources</h1><div class="actions primary-actions reader-actions"><a class="button" href="<?=e($base)?>/findings">Read findings</a><a class="button secondary" href="#resource-list">Inspect sources</a><a class="button secondary" href="<?=e($base)?>">Read study</a></div>
<p class="resource-counts"><strong><?=$resources['source_count']?> distinct source<?=$resources['source_count']===1?'':'s'?></strong> · <?=$resources['contribution_count']?> contributing result<?=$resources['contribution_count']===1?'':'s'?> · <?=$resources['source_record_count']?> attribution records</p>
<form class="source-filters" method="get" action="<?=e($base)?>/resources"><div class="source-search"><label for="source-query">Search sources, authors or claims</label><input id="source-query" name="q" type="search" maxlength="200" value="<?=e($resources['filters']['q'])?>"></div><div class="source-selects"><div><?php select_field('Access','access',[''=>'All access','full_text'=>'Full text','abstract_only'=>'Abstract only','unavailable'=>'Unavailable'],$resources['filters']['access']); ?></div><div><?php select_field('Use','use',[''=>'All uses','used'=>'Used','background'=>'Background','rejected'=>'Rejected','historical'=>'Historical / not recorded'],$resources['filters']['use']); ?></div><button class="source-submit">Filter sources</button></div></form><p class="reader-study-title"><?=e($r['title'])?></p></div>
<div class="reader-content" id="resource-list"><div class="source-resultbar"><p role="status"><?=$resources['matching_sources']?> matching source<?=$resources['matching_sources']===1?'':'s'?> · Page <?=$resources['page']?> of <?=$resources['pages']?></p><a href="<?=e($base)?>/resources">Reset filters</a></div><p class="fine">Search matches a source when any attribution or use matches. Expand it to see every contributing record, including differing access or use declarations. Sources are consolidated by DOI or URL and dataset edition.</p>
<details class="source-policy"><summary>Eligibility and attribution limits</summary><p><?=e($resources['notice'])?></p></details>
<?php if(!$resources['sources']): ?><p>No matching eligible structured sources are available. Historical reference text remains in its contributing result; no inspections or missing attribution have been inferred.</p><?php endif ?>
<?php foreach($resources['sources'] as $group): $first=$group['contributions'][0]['source'];$contributors=array_unique(array_column($group['contributions'],'result_id')); ?><details class="source-group" id="resource-<?=e($group['id'])?>" data-resource><summary><span class="source-title"><?=e($first['title'])?></span><span class="fine"><?=count($contributors)?> contributing result<?=count($contributors)===1?'':'s'?> · <?=count($group['contributions'])?> attribution record<?=count($group['contributions'])===1?'':'s'?></span></summary><div class="source-group-body"><p>Each contributor’s complete attribution, access statement, claims and extraction locations are retained below.</p>
<?php foreach($group['contributions'] as $entry): $source=$entry['source'];$resultBase=$base.($entry['contribution']?'/contributions/':'/results/').$entry['result_id'];$resultView=$entry['contribution']?$base.'#contribution-'.$entry['result_id']:$resultBase; ?><details class="ledger-entry source-record" data-source-record><summary><?=e($entry['display_name']?:'Anonymous volunteer')?> · <?=e($entry['created_at'])?> UTC · <?=e($entry['outcome'])?> · source <?=e($source['id'])?></summary><div class="source-record-body"><h3><?=e($source['title'])?></h3><p><strong><?=e(($source['authors']??'')?:'Authors/organization not recorded')?></strong> · <?=e(($source['publication_date']??'')?:'Publication date not recorded')?> · <?=e(($source['publisher']??'')?:'Journal/publisher not recorded')?></p><p>DOI: <?=e(($source['doi']??'')?:'Not recorded')?> · Dataset edition/version: <?=e(($source['edition']??'')?:'Not recorded or not applicable')?></p>
<?php if($source['url']): ?><p><a href="<?=e($source['url'])?>" rel="noreferrer">Original source · <?=e($source['url'])?></a></p><?php endif ?>
<?php $access=$source['access'];$use=$source['use']??'historical';$label=$access==='unavailable'?'Unavailable source':($access==='abstract_only'?'Abstract-only access':match($use){'used'=>'Inspected and used','background'=>'Background reference','rejected'=>'Rejected evidence',default=>'Historical use not recorded'}); ?><p class="status"><?=e($label)?></p><p>Declared use: <?=e($source['use']??'Not collected')?> · Access: <?=e(str_replace('_',' ',$access))?></p><?=prose($source['access_note'])?><?=prose($source['metadata_note']??'Historical record: detailed attribution was not collected.')?>
<p><a href="<?=e($resultView)?><?=!$entry['contribution']?'#source-'.e($source['id']):''?>">Contributing result · source <?=e($source['id'])?></a> · <?=e($entry['display_name']?:'Anonymous volunteer')?> · <?=e($entry['created_at'])?> UTC · <?=e($entry['outcome'])?></p>
<?php foreach($entry['uses'] as $use): ?><div class="task-brief"><h4><?=e(ucfirst($use['kind']))?> · <?=e($use['title'])?></h4>
<?php if($use['kind']==='claim'): ?><p><a href="<?=e($resultView)?><?=!$entry['contribution']?'#claim-'.e($use['id']):''?>">Read claim <?=e($use['id'])?></a> · <?=e($use['relation'])?> · <?=e($use['locator'])?></p><?php if($use['extraction']): ?><blockquote><?=e($use['extraction'])?></blockquote><?php endif ?><?=prose($use['explanation'])?>
<?php elseif($use['kind']==='dataset'): ?><p><strong><?=e($use['provenance'])?> dataset</strong> · <a href="<?=e($resultBase)?>/resources/datasets/<?=e($use['id'])?>.csv">Download complete table (CSV)</a></p><?php foreach($use['locations'] as $location): if($location['source_id']!==$source['id'])continue; ?><p><?=e($location['locator'])?> · <?=e($location['extraction'])?></p><?php endforeach ?><?php if(!$use['locations']): ?><p>Historical/simulated table: original extraction location not recorded. No original-source inspection is inferred.</p><?php endif ?>
<?php elseif($use['kind']==='calculation'): ?><p><strong>Derived calculation · <?=e($use['status'])?></strong> · <a href="<?=e($resultBase)?>/calculations/<?=e($use['id'])?>/bundle.json">Inputs, code, outputs and unit checks</a> · <a href="<?=e($resultBase)?>#calculations">Contributing calculation</a></p>
<?php foreach($use['inputs'] as $quantity): ?><p><strong><?=e($quantity['id'])?> = <?=e($quantity['value'])?> <?=e($quantity['unit'])?></strong> · <?=e($quantity['provenance'])?> input<br>Source location: <?=e($quantity['source_locator'])?><br>Extracted: <?=e($quantity['extraction'])?><?php if($quantity['derivation']): ?><br>Derivation: <?=e($quantity['derivation'])?><?php endif ?><br>Retained input: <?=e($quantity['file_id'])?> · <?=e($quantity['locator'])?></p><?php endforeach ?><?php if(!$use['inputs']): ?><p>Historical input-to-source locations were not recorded for this source.</p><?php endif ?>
<?php elseif($use['kind']==='derivation'): ?><p><strong>Model-derived arithmetic · not executed or computationally reproduced</strong> · <a href="<?=e($entry['contribution']?$resultView:$resultBase.'/derivations/'.$use['id'].'/bundle.json')?>">Cited inputs, formula, worked steps and limitations</a></p><?php foreach($use['inputs'] as $q): ?><p><?=e($q['id'].': '.$q['value'].' '.$q['unit'])?><br>Source location: <?=e($q['source_locator'])?><br>Extracted: <?=e($q['extraction'])?></p><?php endforeach ?>
<?php elseif($use['kind']==='artifact'): $partial=!$entry['contribution']&&$entry['outcome']==='progress'; ?><a href="<?=e($entry['contribution']?$resultView:($partial?$resultBase.'#visual-spec-'.$use['id']:$resultBase.'/artifacts/'.$use['id']))?>"><?=e($entry['contribution']?'Read visual specification and backing data in contribution':($partial?'Inspect partial visual specification and backing data':'Open linked artifact and backing data'))?></a>
<?php else: ?><a href="<?=e($resultBase)?>#tool-builds">Tool source, versions, tests and methods</a><?php endif ?>
</div><?php endforeach ?><?php if(!$entry['uses']): ?><p>No structured extraction or usage link was supplied. This reference alone is not supporting evidence.</p><?php endif ?></div></details><?php endforeach ?>
</div></details><?php endforeach ?>
<?php if($resources['pages']>1): ?><nav class="pagination" aria-label="Source pages"><?php if($resources['page']>1): ?><a href="<?=e($sourceUrl($resources['page']-1))?>">Previous sources</a><?php endif ?><?php if($resources['page']<$resources['pages']): ?><a href="<?=e($sourceUrl($resources['page']+1))?>">Next sources</a><?php endif ?></nav><?php endif ?>
<details class="source-supplements"><summary>Supporting materials and historical records</summary>

<?php foreach($resources['materials'] as $material): $path=$base.($material['contribution']?'/contributions/':'/results/').$material['result_id'];$view=$material['contribution']?$base.'#contribution-'.$material['result_id']:$path.'#supporting-materials'; ?><section class="task-brief"><h2>Materials · <?=e($material['title'])?></h2><a href="<?=e($view)?>">Full inventory, access instructions and independent audits</a><p>Includes applicable methods, assumptions, retained work and documented failures. Third-party rights remain with their owners.</p><?php foreach($material['files'] as $file): ?><p><a href="<?=e($path)?>/resources/files/<?=e($file['id'])?>"><?=e($file['name'])?></a> · <?=e($file['category'])?> · <?=e($file['rights'])?></p><?php endforeach ?></section><?php endforeach ?>
<?php foreach($resources['historical_metadata'] as $legacy): ?><p><a href="<?=e($base)?><?=!empty($legacy['contribution'])?'#contribution-':'/results/'?><?=e($legacy['result_id'])?>"><?=e($legacy['note'])?></a></p><?php endforeach ?>
<?php if($resources['audit_history']): ?><details class="research-disclosure"><summary>Eligible superseded contribution history</summary><p>These results are audit history. They do not supply current resources or downloads. Corrections replace the current view; original eligible records remain readable.</p><?php foreach($resources['audit_history'] as $history): ?><p><a href="<?=e($base)?><?=!empty($history['contribution'])?'#contribution-':'/results/'?><?=e($history['result_id'])?>"><?=e($history['task_title'])?></a> · <?=e($history['created_at'])?> UTC</p><?php endforeach ?></details><?php endif ?></details></div>
